// src/phylaxTranscriptionProbe.ts
function effectiveModel(provider, model) {
  if (provider === "local") return model?.trim() || "base";
  if (provider === "groq") return GROQ_STT_MODEL;
  if (provider === "openai") return OPENAI_STT_MODEL;
  return model?.trim() || DEFAULT_OPENROUTER_STT_MODEL;
}
function probeUrl(provider, env2) {
  if (provider === "groq") {
    return env2.PHYLAX_GROQ_KEY_CHECK_URL ?? "https://api.groq.com/openai/v1/models";
  }
  if (provider === "openai") {
    return env2.PHYLAX_OPENAI_KEY_CHECK_URL ?? `https://api.openai.com/v1/models/${encodeURIComponent(OPENAI_STT_MODEL)}`;
  }
  return env2.PHYLAX_OPENROUTER_KEY_CHECK_URL ?? "https://openrouter.ai/api/v1/key";
}
function failureMessage(provider, status) {
  if (status === 401 || status === 403)
    return `${provider} rejected this provider key`;
  if (status === 402)
    return `${provider} accepted the key but transcription credit is unavailable`;
  if (status === 429)
    return `${provider} is rate-limiting checks; try again shortly`;
  return `${provider} connection check failed (${status})`;
}
async function probePhylaxTranscriptionProvider({
  provider,
  model,
  key,
  env: env2 = process.env,
  fetchImpl = fetch,
  openRouterCatalog
}) {
  const selectedModel = effectiveModel(provider, model);
  if (provider === "local") {
    return {
      ok: true,
      provider,
      model: selectedModel,
      message: `Local whisper.cpp is configured with ${selectedModel}; the model downloads into durable storage when needed.`
    };
  }
  const credential = key?.trim();
  if (!credential) {
    return {
      ok: false,
      provider,
      model: selectedModel,
      message: `${provider} requires a provider key`,
      reason: "not_configured"
    };
  }
  try {
    const response = await fetchImpl(probeUrl(provider, env2), {
      headers: {
        Authorization: `Bearer ${credential}`,
        Accept: "application/json"
      },
      signal: AbortSignal.timeout(1e4)
    });
    if (!response.ok) {
      const body = (await response.text().catch(() => "")).slice(0, 400);
      return {
        ok: false,
        provider,
        model: selectedModel,
        message: failureMessage(provider, response.status),
        reason: classifyProviderFailure(response.status, parseProviderErrorBody(body).code, body),
        httpStatus: response.status
      };
    }
    if (provider === "groq") {
      const body = await response.json().catch(() => null);
      const available2 = body?.data?.some((entry2) => entry2.id === GROQ_STT_MODEL) ?? false;
      if (!available2) {
        return {
          ok: false,
          provider,
          model: selectedModel,
          message: `Groq accepted the key but ${GROQ_STT_MODEL} is not available to it`,
          reason: "model_unavailable"
        };
      }
    }
    if (provider === "openrouter") {
      const body = await response.json().catch(() => null);
      const remaining = body?.data?.limit_remaining;
      if (typeof remaining === "number" && remaining <= 0) {
        return {
          ok: false,
          provider,
          model: selectedModel,
          message: "OpenRouter accepted the key but its configured limit has no remaining credit",
          reason: "provider_credit_exhausted"
        };
      }
      if (!openRouterCatalog || openRouterCatalog.fallback) {
        return {
          ok: false,
          provider,
          model: selectedModel,
          message: "OpenRouter accepted the key, but live transcription model availability could not be verified",
          reason: "catalog_unverified"
        };
      }
      if (!openRouterCatalog.models.some((candidate) => candidate.id === selectedModel)) {
        return {
          ok: false,
          provider,
          model: selectedModel,
          message: `OpenRouter accepted the key, but ${selectedModel} is not in its live transcription catalog`,
          reason: "model_unavailable"
        };
      }
    }
    return {
      ok: true,
      provider,
      model: selectedModel,
      message: `${provider} accepted the tenant-scoped key; ${selectedModel} is selected for transcription.`
    };
  } catch (error) {
    const detail = error instanceof Error && error.name === "TimeoutError" ? "timed out" : "could not be reached";
    return {
      ok: false,
      provider,
      model: selectedModel,
      message: `${provider} ${detail}; no settings were changed`,
      reason: classifyThrownError(error)
    };
  }
}

