    const messageStatus = sent ? claim.kind === "forwarded_reply" ? "replied" : "failed_notified" : "failed";
    const outboundStatus = sent ? claim.kind === "forwarded_reply" ? "recovery_sent" : "recovery_notice_sent" : "recovery_failed";
